package java.util;
/** A red-black tree ordered by key. */
public class TreeMap<K,V> extends AbstractMap<K,V> implements NavigableMap<K,V>,Cloneable,java.io.Serializable {
 private static final boolean RED=false,BLACK=true;
 private static final class Node<K,V> implements Map.Entry<K,V> {K key;V value;Node<K,V> left,right,parent;boolean color=BLACK;Node(K k,V v,Node<K,V> p){key=k;value=v;parent=p;}public K getKey(){return key;}public V getValue(){return value;}public V setValue(V v){V old=value;value=v;return old;}public boolean equals(Object o){if(!(o instanceof Map.Entry))return false;Map.Entry<?,?> e=(Map.Entry<?,?>)o;return Objects.equals(key,e.getKey())&&Objects.equals(value,e.getValue());}public int hashCode(){return Objects.hashCode(key)^Objects.hashCode(value);}public String toString(){return key+"="+value;}}
 private Node<K,V> root;private int size,modCount;private final Comparator<? super K> comparator;
 public TreeMap(){this((Comparator<? super K>)null);}public TreeMap(Comparator<? super K> c){comparator=c;}public TreeMap(Map<? extends K,? extends V> m){this();putAll(m);} public TreeMap(SortedMap<K,? extends V> m){this(m.comparator());putAll(m);}
 private int compare(Object a,K b){return comparator==null?((Comparable<? super K>)a).compareTo(b):comparator.compare((K)a,b);}
 private Node<K,V> find(Object k){if(k==null&&comparator==null)throw new NullPointerException();Node<K,V> p=root;while(p!=null){int c=compare(k,p.key);if(c==0)return p;p=c<0?p.left:p.right;}return null;}
 public int size(){return size;}public boolean containsKey(Object k){return find(k)!=null;}public V get(Object k){Node<K,V> p=find(k);return p==null?null:p.value;}public Comparator<? super K> comparator(){return comparator;}
 public V put(K k,V v){if(root==null){compare(k,k);root=new Node<K,V>(k,v,null);size=1;modCount++;return null;}Node<K,V> p=root,parent;int c;do{parent=p;c=compare(k,p.key);if(c<0)p=p.left;else if(c>0)p=p.right;else return p.setValue(v);}while(p!=null);Node<K,V> n=new Node<K,V>(k,v,parent);if(c<0)parent.left=n;else parent.right=n;fixInsertion(n);size++;modCount++;return null;}
 public V remove(Object k){Node<K,V> p=find(k);if(p==null)return null;V old=p.value;delete(p);return old;}public void clear(){if(size>0){root=null;size=0;modCount++;}}
 private Node<K,V> first(){Node<K,V> p=root;if(p!=null)while(p.left!=null)p=p.left;return p;}private Node<K,V> last(){Node<K,V> p=root;if(p!=null)while(p.right!=null)p=p.right;return p;}
 public K firstKey(){Node<K,V> p=first();if(p==null)throw new NoSuchElementException();return p.key;}public K lastKey(){Node<K,V> p=last();if(p==null)throw new NoSuchElementException();return p.key;}
 private Node<K,V> successor(Node<K,V> p){if(p.right!=null){p=p.right;while(p.left!=null)p=p.left;return p;}Node<K,V> x=p.parent;while(x!=null&&p==x.right){p=x;x=x.parent;}return x;}
 private static <K,V> boolean color(Node<K,V> p){return p==null?BLACK:p.color;}private static <K,V> Node<K,V> parent(Node<K,V> p){return p==null?null:p.parent;}private static <K,V> Node<K,V> left(Node<K,V> p){return p==null?null:p.left;}private static <K,V> Node<K,V> right(Node<K,V> p){return p==null?null:p.right;}private static <K,V> void color(Node<K,V> p,boolean c){if(p!=null)p.color=c;}
 private void rotateLeft(Node<K,V> p){if(p==null)return;Node<K,V> r=p.right;p.right=r.left;if(r.left!=null)r.left.parent=p;r.parent=p.parent;if(p.parent==null)root=r;else if(p==p.parent.left)p.parent.left=r;else p.parent.right=r;r.left=p;p.parent=r;}
 private void rotateRight(Node<K,V> p){if(p==null)return;Node<K,V> l=p.left;p.left=l.right;if(l.right!=null)l.right.parent=p;l.parent=p.parent;if(p.parent==null)root=l;else if(p==p.parent.right)p.parent.right=l;else p.parent.left=l;l.right=p;p.parent=l;}
 private void fixInsertion(Node<K,V> x){x.color=RED;while(x!=null&&x!=root&&color(parent(x))==RED){if(parent(x)==left(parent(parent(x)))){Node<K,V> y=right(parent(parent(x)));if(color(y)==RED){color(parent(x),BLACK);color(y,BLACK);color(parent(parent(x)),RED);x=parent(parent(x));}else{if(x==right(parent(x))){x=parent(x);rotateLeft(x);}color(parent(x),BLACK);color(parent(parent(x)),RED);rotateRight(parent(parent(x)));}}else{Node<K,V> y=left(parent(parent(x)));if(color(y)==RED){color(parent(x),BLACK);color(y,BLACK);color(parent(parent(x)),RED);x=parent(parent(x));}else{if(x==left(parent(x))){x=parent(x);rotateRight(x);}color(parent(x),BLACK);color(parent(parent(x)),RED);rotateLeft(parent(parent(x)));}}}root.color=BLACK;}
 private void delete(Node<K,V> p){modCount++;size--;if(p.left!=null&&p.right!=null){Node<K,V> s=successor(p);p.key=s.key;p.value=s.value;p=s;}Node<K,V> replacement=p.left!=null?p.left:p.right;if(replacement!=null){replacement.parent=p.parent;if(p.parent==null)root=replacement;else if(p==p.parent.left)p.parent.left=replacement;else p.parent.right=replacement;p.left=p.right=p.parent=null;if(p.color==BLACK)fixDeletion(replacement);}else if(p.parent==null)root=null;else{if(p.color==BLACK)fixDeletion(p);if(p.parent!=null){if(p==p.parent.left)p.parent.left=null;else if(p==p.parent.right)p.parent.right=null;p.parent=null;}}}
 private void fixDeletion(Node<K,V> x){while(x!=root&&color(x)==BLACK){if(x==left(parent(x))){Node<K,V> s=right(parent(x));if(color(s)==RED){color(s,BLACK);color(parent(x),RED);rotateLeft(parent(x));s=right(parent(x));}if(color(left(s))==BLACK&&color(right(s))==BLACK){color(s,RED);x=parent(x);}else{if(color(right(s))==BLACK){color(left(s),BLACK);color(s,RED);rotateRight(s);s=right(parent(x));}color(s,color(parent(x)));color(parent(x),BLACK);color(right(s),BLACK);rotateLeft(parent(x));x=root;}}else{Node<K,V> s=left(parent(x));if(color(s)==RED){color(s,BLACK);color(parent(x),RED);rotateRight(parent(x));s=left(parent(x));}if(color(right(s))==BLACK&&color(left(s))==BLACK){color(s,RED);x=parent(x);}else{if(color(left(s))==BLACK){color(right(s),BLACK);color(s,RED);rotateLeft(s);s=left(parent(x));}color(s,color(parent(x)));color(parent(x),BLACK);color(left(s),BLACK);rotateRight(parent(x));x=root;}}}color(x,BLACK);}
 public Set<Map.Entry<K,V>> entrySet(){return new AbstractSet<Map.Entry<K,V>>(){public int size(){return size;}public void clear(){TreeMap.this.clear();}public Iterator<Map.Entry<K,V>> iterator(){return new Iterator<Map.Entry<K,V>>(){Node<K,V> next=first(),last;int expected=modCount;public boolean hasNext(){return next!=null;}public Map.Entry<K,V> next(){if(expected!=modCount)throw new ConcurrentModificationException();if(next==null)throw new NoSuchElementException();last=next;next=successor(next);return last;}public void remove(){if(expected!=modCount)throw new ConcurrentModificationException();if(last==null)throw new IllegalStateException();if(last.left!=null&&last.right!=null)next=last;delete(last);last=null;expected=modCount;}};}};}
 public Object clone(){TreeMap<K,V> t=new TreeMap<K,V>(comparator);t.putAll(this);return t;}
 private NavigableMap<K,V> view(){return new View(false,null,false,false,null,false,false);}
 public Entry<K,V> lowerEntry(K k){return view().lowerEntry(k);} public K lowerKey(K k){return view().lowerKey(k);} public Entry<K,V> floorEntry(K k){return view().floorEntry(k);} public K floorKey(K k){return view().floorKey(k);} public Entry<K,V> ceilingEntry(K k){return view().ceilingEntry(k);} public K ceilingKey(K k){return view().ceilingKey(k);} public Entry<K,V> higherEntry(K k){return view().higherEntry(k);} public K higherKey(K k){return view().higherKey(k);}
 public Entry<K,V> firstEntry(){return view().firstEntry();} public Entry<K,V> lastEntry(){return view().lastEntry();} public Entry<K,V> pollFirstEntry(){return view().pollFirstEntry();} public Entry<K,V> pollLastEntry(){return view().pollLastEntry();}
 public NavigableMap<K,V> descendingMap(){return view().descendingMap();} public NavigableSet<K> navigableKeySet(){return new KeySet<K,V>(this);} public NavigableSet<K> descendingKeySet(){return descendingMap().navigableKeySet();} public NavigableSet<K> keySet(){return navigableKeySet();}
 public NavigableMap<K,V> subMap(K a,boolean ai,K b,boolean bi){return view().subMap(a,ai,b,bi);} public NavigableMap<K,V> headMap(K b,boolean bi){return view().headMap(b,bi);} public NavigableMap<K,V> tailMap(K a,boolean ai){return view().tailMap(a,ai);} public SortedMap<K,V> subMap(K a,K b){return subMap(a,true,b,false);} public SortedMap<K,V> headMap(K b){return headMap(b,false);} public SortedMap<K,V> tailMap(K a){return tailMap(a,true);}
 static class KeySet<K,V> extends AbstractSet<K> implements NavigableSet<K>{
  final NavigableMap<K,V> m; KeySet(NavigableMap<K,V> m){this.m=m;} public int size(){return m.size();} public boolean contains(Object k){return m.containsKey(k);} public boolean remove(Object k){int n=size();m.remove(k);return size()!=n;} public void clear(){m.clear();} public Iterator<K> iterator(){final Iterator<Entry<K,V>> i=m.entrySet().iterator();return new Iterator<K>(){public boolean hasNext(){return i.hasNext();}public K next(){return i.next().getKey();}public void remove(){i.remove();}};} public Iterator<K> descendingIterator(){return descendingSet().iterator();} public Comparator<? super K> comparator(){return m.comparator();} public K first(){return m.firstKey();} public K last(){return m.lastKey();} public K lower(K k){return m.lowerKey(k);} public K floor(K k){return m.floorKey(k);} public K ceiling(K k){return m.ceilingKey(k);} public K higher(K k){return m.higherKey(k);} public K pollFirst(){Entry<K,V> e=m.pollFirstEntry();return e==null?null:e.getKey();} public K pollLast(){Entry<K,V> e=m.pollLastEntry();return e==null?null:e.getKey();} public NavigableSet<K> descendingSet(){return new KeySet<K,V>(m.descendingMap());} public NavigableSet<K> subSet(K a,boolean ai,K b,boolean bi){return new KeySet<K,V>(m.subMap(a,ai,b,bi));} public NavigableSet<K> headSet(K b,boolean bi){return new KeySet<K,V>(m.headMap(b,bi));} public NavigableSet<K> tailSet(K a,boolean ai){return new KeySet<K,V>(m.tailMap(a,ai));} public SortedSet<K> subSet(K a,K b){return subSet(a,true,b,false);} public SortedSet<K> headSet(K b){return headSet(b,false);} public SortedSet<K> tailSet(K a){return tailSet(a,true);}
 }
 private class View extends AbstractMap<K,V> implements NavigableMap<K,V>{
  final boolean hasLo,loInc,hasHi,hiInc,desc; final K lo,hi;
  View(boolean hl,K l,boolean li,boolean hh,K h,boolean hi,boolean d){hasLo=hl;lo=l;loInc=li;hasHi=hh;this.hi=h;hiInc=hi;desc=d;}
  boolean in(K k){return (!hasLo||compare(k,lo)>0||(loInc&&compare(k,lo)==0))&&(!hasHi||compare(k,hi)<0||(hiInc&&compare(k,hi)==0));}
  void endpoint(K k,boolean inclusive){compare(k,k);if(hasLo&&(compare(k,lo)<0||(inclusive&&!loInc&&compare(k,lo)==0)))throw new IllegalArgumentException();if(hasHi&&(compare(k,hi)>0||(inclusive&&!hiInc&&compare(k,hi)==0)))throw new IllegalArgumentException();}
  public Comparator<? super K> comparator(){return desc?Collections.reverseOrder((Comparator<K>)TreeMap.this.comparator):TreeMap.this.comparator;} public int size(){int n=0;for(Entry<K,V> e:entrySet())n++;return n;} public boolean containsKey(Object k){return in((K)k)&&TreeMap.this.containsKey(k);} public V get(Object k){return in((K)k)?TreeMap.this.get(k):null;} public V put(K k,V v){if(!in(k))throw new IllegalArgumentException();return TreeMap.this.put(k,v);} public V remove(Object k){return in((K)k)?TreeMap.this.remove(k):null;}
  public Set<Entry<K,V>> entrySet(){return new AbstractSet<Entry<K,V>>(){public int size(){return View.this.size();}public Iterator<Entry<K,V>> iterator(){return new Iterator<Entry<K,V>>(){Node<K,V> nextNode=initial();K lastKey;boolean hasLast;int expected=modCount; Node<K,V> initial(){Node<K,V> p=desc?last():first();while(p!=null&&!in(p.key))p=desc?predecessor(p):successor(p);return p;} public boolean hasNext(){return nextNode!=null;}public Entry<K,V> next(){if(expected!=modCount)throw new ConcurrentModificationException();if(nextNode==null)throw new NoSuchElementException();Node<K,V> p=nextNode;lastKey=p.key;hasLast=true;Node<K,V> n=desc?predecessor(p):successor(p);nextNode=n!=null&&in(n.key)?n:null;return p;}public void remove(){if(expected!=modCount)throw new ConcurrentModificationException();if(!hasLast)throw new IllegalStateException();Node<K,V> victim=find(lastKey);if(!desc&&victim.left!=null&&victim.right!=null)nextNode=victim;TreeMap.this.remove(lastKey);hasLast=false;expected=modCount;}};}};}
  Entry<K,V> seek(K k,int op){compare(k,k);Entry<K,V> best=null;for(Entry<K,V> e:entrySet()){int c=compare(e.getKey(),k);if(desc)c=-c;if((op==-2&&c<0)||(op==-1&&c<=0)){best=e;}else if((op==1&&c>=0)||(op==2&&c>0)){best=e;break;}}return best==null?null:new SimpleImmutableEntry<K,V>(best);}
  K key(Entry<K,V> e){return e==null?null:e.getKey();} public Entry<K,V> lowerEntry(K k){return seek(k,-2);}public K lowerKey(K k){return key(lowerEntry(k));}public Entry<K,V> floorEntry(K k){return seek(k,-1);}public K floorKey(K k){return key(floorEntry(k));}public Entry<K,V> ceilingEntry(K k){return seek(k,1);}public K ceilingKey(K k){return key(ceilingEntry(k));}public Entry<K,V> higherEntry(K k){return seek(k,2);}public K higherKey(K k){return key(higherEntry(k));}
  public Entry<K,V> firstEntry(){Iterator<Entry<K,V>> i=entrySet().iterator();return i.hasNext()?new SimpleImmutableEntry<K,V>(i.next()):null;}public Entry<K,V> lastEntry(){return descendingMap().firstEntry();}public K firstKey(){Entry<K,V> e=firstEntry();if(e==null)throw new NoSuchElementException();return e.getKey();}public K lastKey(){Entry<K,V> e=lastEntry();if(e==null)throw new NoSuchElementException();return e.getKey();}public Entry<K,V> pollFirstEntry(){Iterator<Entry<K,V>> i=entrySet().iterator();if(!i.hasNext())return null;Entry<K,V> e=new SimpleImmutableEntry<K,V>(i.next());i.remove();return e;}public Entry<K,V> pollLastEntry(){return descendingMap().pollFirstEntry();}
  public NavigableMap<K,V> descendingMap(){return new View(hasLo,lo,loInc,hasHi,hi,hiInc,!desc);}public NavigableSet<K> navigableKeySet(){return new KeySet<K,V>(this);}public NavigableSet<K> keySet(){return navigableKeySet();}public NavigableSet<K> descendingKeySet(){return descendingMap().navigableKeySet();}
  public NavigableMap<K,V> subMap(K a,boolean ai,K b,boolean bi){endpoint(a,ai);endpoint(b,bi);if((desc?-compare(a,b):compare(a,b))>0)throw new IllegalArgumentException();return desc?new View(true,b,bi,true,a,ai,true):new View(true,a,ai,true,b,bi,false);}public NavigableMap<K,V> headMap(K b,boolean bi){endpoint(b,bi);return desc?new View(true,b,bi,hasHi,hi,hiInc,true):new View(hasLo,lo,loInc,true,b,bi,false);}public NavigableMap<K,V> tailMap(K a,boolean ai){endpoint(a,ai);return desc?new View(hasLo,lo,loInc,true,a,ai,true):new View(true,a,ai,hasHi,hi,hiInc,false);}public SortedMap<K,V> subMap(K a,K b){return subMap(a,true,b,false);}public SortedMap<K,V> headMap(K b){return headMap(b,false);}public SortedMap<K,V> tailMap(K a){return tailMap(a,true);}
 }
 private Node<K,V> predecessor(Node<K,V> p){if(p.left!=null){p=p.left;while(p.right!=null)p=p.right;return p;}Node<K,V> x=p.parent;while(x!=null&&p==x.left){p=x;x=x.parent;}return x;}

}
